PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?zone ?tp ?temp ?hset ?cset ?tsid WHERE {
  ?zone rdf:type brick:Zone; brick:hasName "Core_mid" .
  ?tp brick:hasLocation ?zone ; brick:isOfType brick:TemperatureSensor .
  ?ts rdf:type brick:TemperatureSetpoint ; brick:hasLocation ?zone .
}

